insert into public.run_guides (slug, level, position, title, body_md, try_this, is_premium, is_published)
values ('warm-up-cool-down', 'starter', 4, 'Warm up and cool down in five minutes', 'A warm-up raises your heart rate and loosens your joints so the first minutes of running feel smooth instead of stiff.

- Walk briskly for 3–5 minutes.
- Add a few leg swings, gentle hip circles and ankle rolls.
- Start your run at your easiest pace and let it build.

Your plan already includes a 5-minute warm-up and cool-down walk. To cool down, walk until your breathing settles, then do light stretches for your calves, thighs and hips. Hold each stretch for about 30 seconds. Skip deep static stretching before running: save it for after.',
  'Add 10 leg swings on each leg to your next warm-up walk.', false, true)
