insert into public.run_guides (slug, level, position, title, body_md, try_this, is_premium, is_published)
values ('build-up-gradually', 'builder', 1, 'Build up gradually: the 10% guide', 'Most running injuries come from doing too much too soon, not from running itself.

A common guideline is to increase your total weekly running time or distance by no more than about 10% a week. It isn''t a strict law, but it''s a useful brake when you feel great and want to double everything.

- Change one thing at a time: more time, or more speed, not both in the same week.
- Every 3–4 weeks, have a lighter week. Your plan builds these in.
- Treat sleep, stress and illness as part of your training load.

Fitness arrives in waves. A lighter week is when your body absorbs the hard work.',
  'Add up last week''s running minutes and plan this week within 10% of it.', true, true)
