insert into public.run_guides (slug, level, position, title, body_md, try_this, is_premium, is_published)
values ('your-first-intervals', 'builder', 3, 'Your first intervals', 'Intervals are short, faster efforts with easy recovery between them. They teach your body to run faster and make your normal pace feel easier.

- Faster means hard but controlled, about 8 out of 10, not a flat-out sprint.
- Recovery is a slow jog or walk until your breathing settles.
- The last repeat should feel as strong as the first. If you fade badly, you started too fast.

Always warm up properly first, and keep intervals to once a week while you''re building. On a flat road, a track or a quiet park path, you''ll get the most out of every repeat.',
  'In your next interval session, aim to run the last repeat at the same effort as the first.', true, true)
