insert into public.run_guides (slug, level, position, title, body_md, try_this, is_premium, is_published)
values ('tempo-runs', 'builder', 4, 'Tempo runs: comfortably hard', 'A tempo run is a steady block at a pace that feels comfortably hard. You can speak only a few words at a time, but you could hold it for about an hour if you had to.

Tempo running raises the pace you can sustain before fatigue builds quickly, which is what longer races demand.

- Start with 10–15 minutes and build to 30.
- Settle into the pace gradually over the first few minutes.
- If your breathing becomes ragged, ease off: you''ve drifted into racing.

On hilly routes, run tempo by effort rather than by pace.',
  'During your next tempo run, check you can say about four words at a time, no more.', true, true)
