insert into public.run_guides (slug, level, position, title, body_md, try_this, is_premium, is_published)
values ('the-long-run', 'builder', 5, 'The long run', 'The weekly long run is the backbone of every distance plan. It builds endurance, strengthens your legs and teaches you to stay relaxed for longer.

- Run it slowly: slower than your other easy runs is fine.
- Grow it gradually, about 5–10 minutes a week, with lighter weeks between.
- Carry water on runs over an hour, especially in the heat.

Plan a route you enjoy, or loops past home so you can refill water. Walking breaks on long runs are allowed and used by many experienced marathoners.',
  'Plan your next long-run route so it passes a water point or home after about 40 minutes.', true, true)
