insert into public.run_guides (slug, level, position, title, body_md, try_this, is_premium, is_published)
values ('strength-for-runners', 'builder', 6, 'Strength training for runners', 'Runners who do some strength work tend to get injured less and run more efficiently. Two short sessions a week are enough, and your Goal4Me workouts count.

Focus on:

- Calves: calf raises, slow on the way down.
- Hips and glutes: glute bridges, side leg raises, lunges.
- Core: planks and dead bugs to keep you stable when tired.
- Single-leg work: running is a series of single-leg landings.

Do strength on easy days or after an easy run, not the day before a hard session or long run.',
  'Add 3 sets of 15 slow calf raises after your next easy run.', true, true)
