insert into public.run_guides (slug, level, position, title, body_md, try_this, is_premium, is_published)
values ('the-80-20-rule', 'racer', 1, 'The 80/20 rule', 'Studies of endurance athletes show that most of them do about 80% of their training at low intensity and about 20% hard.

Many amateur runners do the opposite. Every run ends up "medium": too hard to recover from, too easy to make you much faster.

- Keep easy days truly easy, using the talk test.
- Make the hard sessions count: properly warmed up and focused.
- If you''re always tired, the easy days are probably too fast.

Your plan follows this pattern: one quality session a week and easy running around it.',
  'Look at your last week of runs: were your easy runs really conversational?', true, true)
