insert into public.run_guides (slug, level, position, title, body_md, try_this, is_premium, is_published)
values ('hydration-and-fuel', 'racer', 2, 'Hydration and fuel', 'For runs under an hour, most people need nothing more than water before and after. For longer runs, what you drink and eat starts to matter.

- Drink to thirst during runs; don''t force down large amounts.
- In heat, or on runs over an hour, carry water and consider an electrolyte drink to replace salt.
- On runs over 75–90 minutes, take some carbohydrate: a sports drink, gel, banana or a few sweets.
- Eat a carbohydrate-rich meal 2–3 hours before a long run or race.

Practise your fuel on long runs. Race day is never the time to try something new.',
  'On your next long run, practise taking a small snack or sports drink after 45 minutes.', true, true)
