insert into public.run_guides (slug, level, position, title, body_md, try_this, is_premium, is_published)
values ('running-in-heat', 'racer', 3, 'Running in heat, altitude and the dark', 'Heat is the biggest challenge for runners in much of Africa and India. Your body sends blood to the skin to cool down, so the same pace feels harder.

- Run early in the morning or in the evening.
- Slow down by effort and accept slower times on hot days.
- Wear light colours and a cap, and carry water.
- Stop and get into shade if you feel dizzy, confused or stop sweating.

At altitude (such as Harare or Johannesburg) the same applies: easy runs by feel, not by pace from sea level.

In the dark, wear reflective or bright kit, run facing traffic where there is no pavement, and tell someone your route.',
  'On your next hot day, run by the talk test only and ignore your pace completely.', true, true)
