insert into public.run_guides (slug, level, position, title, body_md, try_this, is_premium, is_published)
values ('recovery-and-sleep', 'racer', 4, 'Recovery, sleep and rest days', 'Training breaks you down; recovery is when you get fitter. Skip it and the work doesn''t pay off.

- Sleep is the most powerful recovery tool: aim for 7–9 hours.
- Take at least one complete rest day a week.
- Eat enough, including protein and carbohydrate after hard sessions and long runs.
- Easy days should leave you feeling better, not worse.

Watch for signs you need more rest: a heavy, flat feeling on every run, poor sleep, low mood, or getting ill often. If they last more than a few days, take an extra easy or rest day.',
  'Go to bed 30 minutes earlier the night before your next long run.', true, true)
