insert into public.run_guides (slug, level, position, title, body_md, try_this, is_premium, is_published)
values ('first-half-marathon', 'racer', 6, 'Getting ready for your first half marathon', 'A half marathon is 21.1 km. With a steady plan, most runners who can run 10K are ready in about three months.

In the final weeks:

- Run your last long run about 2 weeks before race day, then ease off.
- Lay out your kit the night before: shoes you''ve trained in, nothing new.
- Eat a familiar breakfast 2–3 hours before the start.
- Arrive early, warm up gently and start near runners of your pace.

During the race, drink at water stations, use the fuel you practised, and enjoy it. Your first race is automatically a personal best.',
  'Choose a race date and add it to your plan so it builds up to that day.', true, true)
