insert into public.run_guides (slug, level, position, title, body_md, try_this, is_premium, is_published)
values ('phases-of-training', 'pro', 1, 'Phases of training: base, build, peak, taper', 'Serious training plans are organised in phases, each with a job.

- Base: lots of easy running to build aerobic fitness and durability.
- Build: add more specific work, such as tempo runs and race-pace sections.
- Peak: the hardest few weeks, including the longest runs.
- Taper: cut volume so you arrive at race day fresh.

When your race is far away, Goal4Me adds base weeks at the start of your plan. Respect each phase. Base weeks feel easy, and that''s the point: they let you handle the hard weeks later.',
  'Look at your plan and find where each phase starts and ends.', true, true)
