insert into public.run_guides (slug, level, position, title, body_md, try_this, is_premium, is_published)
values ('marathon-fuelling', 'pro', 3, 'Marathon fuelling', 'In a marathon, your body''s stored carbohydrate runs low after about 90–120 minutes. That''s "the wall". Taking carbohydrate during the race delays it.

- Aim for about 30–60 g of carbohydrate per hour from gels, sports drink or chews.
- Start early, around 30–45 minutes in, and keep taking it little and often.
- Train your gut: practise race fuelling on every long run.
- Eat more carbohydrate than usual in the 2 days before the race.

Find out what drinks and gels the race provides, and practise with them or carry your own.',
  'On your next long run, take your first fuel at 40 minutes and every 30 minutes after.', true, true)
