insert into public.run_guides (slug, level, position, title, body_md, try_this, is_premium, is_published)
values ('how-to-taper', 'pro', 4, 'How to taper', 'In the final 2–3 weeks before a marathon, you cut back your running so your body can recover and absorb the training. This is called the taper.

- Cut your total running by about 20–30% each week.
- Keep a little speed so your legs stay sharp.
- Keep the same number of run days; just make each one shorter.
- Sleep more and eat well.

Many runners feel restless, heavy or even get phantom aches during a taper. It''s normal. Trust it: you can''t gain fitness in the last week, but you can arrive tired.',
  'Write down three things you''ll do with the extra time during your taper.', true, true)
