insert into public.run_guides (slug, level, position, title, body_md, try_this, is_premium, is_published)
values ('marathon-race-day', 'pro', 5, 'Marathon race-day plan', 'A marathon is won or lost by decisions in the first half.

- The day before: rest, hydrate, eat familiar food and lay out your kit.
- Race morning: breakfast 3 hours before, toilet early, warm up gently.
- Kilometres 1–10: hold back. Start at or just slower than goal pace.
- Kilometres 10–30: settle in, fuel on schedule, drink at stations.
- Kilometres 30–42: this is the race. Focus on form, short steps and the next kilometre.

Have an A, B and C goal: a great day, a good day, and finishing proud. Being flexible means you won''t give up if the A goal slips away.',
  'Write your A, B and C goals for your race and save them in your run notes.', true, true)
