insert into public.run_guides (slug, level, position, title, body_md, try_this, is_premium, is_published)
values ('running-for-life', 'pro', 6, 'After the race: running for life', 'After a marathon, your muscles and immune system need time to recover, even if you feel fine.

- Take a few days off, then a week or two of short, easy runs.
- Don''t race again or start a new hard block for at least 3–4 weeks.
- Look back: what went well, and what would you change?

To keep running for years, balance the hard seasons with easy ones, keep up your strength work, replace your shoes, and enjoy running with no plan at all sometimes. Then pick your next challenge, whether that''s a faster 5K, a trail race or helping a friend start Couch to 5K.',
  'Pick your next goal and choose the programme that fits it.', true, true)
